#!/bin/bash
# build.sh [emu|ptx|all] (agent n7-gkjs).  Sources are generated by mkgkjs.py from the production sources (the script is the diff).
#   hosts:   gkjs.exe (7 symbols), gkjs6.exe, gkjs5.exe          gcc -O2
#   kernels: gkjs.ptx (LL = 6), gkjs6.ptx (5), gkjs5.ptx (4)     nvcc, switches LEARN RC NR=3 as production
#   emu:     gkjs_emu.exe, gkjs6_emu.exe, gkjs5_emu.exe          host with -DEMU + emu.cpp (the kernels on the processor)
#   CPU reference: kref.exe (7 symbols; = krows/kfast_js.c), kref6.exe, kref5.exe
#   run/ = gkjs.exe + gkjs.ptx: the pair that kparts.sh uses
cd "$(dirname "$0")"
PY=../../../../.venv/Scripts/python.exe
$PY mkgkjs.py || exit 1
what=${1:-all}
for v in 7 6 5; do
  sfx=$v; [ $v == 7 ] && sfx=
  gcc -O2 -DNSYM=$v -o gkjs$sfx.exe gkjs.c || exit 1
  gcc -O2 -DNSYM=$v -o kref$sfx.exe kref.c || exit 1
  if [ $what != ptx ]; then
    g++ -O2 -DLEARN=1 -DRC=1 -DNR=3 -DLL=$((v - 1)) -c -o emu$sfx.o emu.cpp || exit 1
    gcc -O2 -DNSYM=$v -DEMU -c -o gkjs_emu$sfx.o gkjs.c || exit 1
    g++ -O2 -o gkjs${sfx}_emu.exe gkjs_emu$sfx.o emu$sfx.o || exit 1
    rm -f emu$sfx.o gkjs_emu$sfx.o
  fi
  if [ $what != emu ]; then
    cmd //c ".\build_ptx.bat gkjs.cu gkjs$sfx.ptx $((v - 1))" || exit 1
  fi
done
if [ $what != emu ]; then mkdir -p run; cp gkjs.exe gkjs.ptx run/; fi
ls -la *.exe *.ptx 2>/dev/null | awk '{print $5, $9}'
